        "easyExplanation": "\n          <h4>Негізгі тұжырымдама мен басты қағидалар:</h4>\n          <p><b>Кинематика</b> — дененің <i>неліктен</i> қозғалатынын сұрамайды, тек <b>қалай</b> қозғалатынын (орын ауыстыру, жылдамдық, үдеу) зерттейді.</p>\n          <ul>\n            <li><b>Жол ($L$) мен Орын ауыстыру ($\\vec{S}$):</b> Дүкенге барып, үйге қайтсаң — жолың $L = 2d$, бірақ орын ауыстыруың $S = 0$!</li>\n            <li><b>Орташа жылдамдықтың басты тұзағы:</b> Егер жолдың <i>жартысын</i> $v_1$, екінші <i>жартысын</i> $v_2$ жылдамдықпен жүрсе: $\\langle v \\rangle = \\frac{2v_1 v_2}{v_1 + v_2}$ (арифметикалық орта ЕМЕС!). Ал егер <i>уақыттың</i> жартысын жүрсе ғана: $\\langle v \\rangle = \\frac{v_1 + v_2}{2}$.</li>\n            <li><b>Тежелу жолы мен уақыты:</b> Дене тоқтағанда $v = 0$ болады, сондықтан $S_{теж} = \\frac{v_0^2}{2a}$ және $t_{теж} = \\frac{v_0}{a}$. Жылдамдық 2 есе артса, тежелу жолы <b>4 есе</b> артады!</li>\n            <li><b>Горизонталь және бұрышпен лақтырылған дене:</b> $OX$ осі бойынша қозғалыс әрқашан <b>бірқалыпты</b> ($v_x = v_0 \\cos\\alpha = \\text{const}$), ал $OY$ осі бойынша — еркін түсу ($a_y = -g$). Ең алысқа ұшу бұрышы: $\\alpha = 45^\\circ$.</li>\n          </ul>\n        ",
