        "easyExplanation": "\n          <h4>Негізгі тұжырымдама мен басты қағидалар:</h4>\n          <p><b>Динамика</b> — қозғалыстың <b>себебін (күштерді)</b> зерттейді. Ең басты заң: барлық күштердің векторлық қосындысы $\\sum \\vec{F} = m\\vec{a}$.</p>\n          <ul>\n            <li><b>Лифт ережесі (Салмақ $P$):</b> Лифт <b>жоғары</b> үдеумен ($a \\uparrow$) қозғалса немесе төмен тежелсе — адам ауырлайды: $P = m(g + a)$. Лифт <b>төмен</b> үдеумен ($a \\downarrow$) қозғалса — жеңілдейді: $P = m(g - a)$. Еркін құласа ($a = g$) — <b>салмақсыздық</b> ($P = 0$).</li>\n            <li><b>Көлбеу жазықтық:</b> Денені төмен сырғанататын күш: $F_{\\parallel} = mg\\sin\\alpha$, ал жазықтыққа қысатын күш (тірек реакциясы): $N = mg\\cos\\alpha$. Сондықтан үйкеліс күші: $F_{үйк} = \\mu mg\\cos\\alpha$.</li>\n            <li><b>Серіппелерді жалғау:</b> Тізбектей жалғанса қатаңдық <b>азаяды</b> ($\\frac{1}{k_{тіз}} = \\frac{1}{k_1} + \\frac{1}{k_2}$), параллель жалғанса қатаңдық <b>қосылады</b> ($k_{пар} = k_1 + k_2$). Серіппені $n$ тең бөлікке кессе, әр бөліктің қатаңдығы $n$ есе артады!</li>\n          </ul>\n        ",
