        "easyExplanation": "\n          <h4>Негізгі тарихи фактілер мен даталар хронологиясы:</h4>\n          <ul>\n            <li><b>Ежелгі тас дәуірі (Палеолит, б.з.б. 2.6 млн – 12 мың ж.):</b> Алғашқы адамдар іздері — Қаратау (Шабақты, Бөріқазған, Тәңірқазған), Орталық Қазақстан (Құдайкөл, Обалысай), Шығыс Қазақстан (Қанай). Екі жағынан өңделген тас құрал — <b>бифас</b>, бір жағынан — <b>чоппер</b>. Мұстьер кезеңінің ең үздік ескерткіші — <b>Уәлиханов атындағы тұрақ</b> (Оңт. Қазақстан).</li>\n            <li><b>Орта тас дәуірі (Мезолит, б.з.б. 12–5 мың ж.):</b> Ең басты жаңалықтар: <b>садақ пен жебе</b> және <b>микролиттер</b> (ұсақ тас құралдар, 1–2 см), бумеранг, қайық. Мұздық еріп, ірі жануарлар (мамонт) жойылды.</li>\n            <li><b>Жаңа тас дәуірі (Неолит, б.з.б. 5–3 мың ж.):</b> «Неолиттік төңкеріс» — <b>өнім өндіруші шаруашылық</b> (егіншілік пен мал шаруашылығы) және <b>қыш құмыра жасау</b> (керамика), дәнүккіш, тоқымашылық. Тұрақтар: Сексеуіл, Қараүңгір, Зеленая Балка, Пеньки.</li>\n            <li><b>Мыс-тас дәуірі (Энеолит, б.з.б. 3000–2800 ж.):</b> <b>Ботай мәдениеті</b> (Солт. Қазақстан, В. Зайберт зерттеген, 158 тұрғын үй, <b>жылқыны әлемде алғаш қолға үйрету</b>) және <b>Шебір</b> (Маңғыстау).</li>\n            <li><b>Қола дәуірі (б.з.б. ІІ мыңжылдық – б.з.б. VIII ғ.):</b> Мыс + Қалайы = Қола. <b>Андрон мәдениеті</b> (Алакөл, Федоров), кейінгі қола — <b>Беғазы-Дәндібай мәдениеті</b> (Орталық Қазақстан, Ә. Марғұлан зерттеген). Петроглифтер (жартас суреттері): <b>Тамғалы, Ешкіөлмес, Баянжүрек</b>. Протоқала: <b>Арқайым</b>.</li>\n          </ul>\n        ",
