        "easyExplanation": "\n          <h4>Ежелгі тайпалық одақтар кестесі:</h4>\n          <ul>\n            <li><b>Сақтар (б.з.б. VIII – III ғ.):</b> Парсы деректерінде «Құдіретті еркектер», грек деректерінде «Азиялық скифтер». 3 тобы:\n              1) <b>Сақ-тиграхауда</b> (шошақ бөріктілер) — Жетісу, Тянь-Шань (Есік обасы — «Алтын адам», Кемал Ақышев, 1969 ж., б.з.б. V–IV ғ.; Бесшатыр).\n              2) <b>Сақ-парадарайа</b> (теңіздің арғы жағындағылар) — Арал, Сырдарияның төменгі ағысы (Шірік-Рабат, Бәбіш-Молда).\n              3) <b>Сақ-хаомаварга</b> (хаома сусынын дайындаушылар) — Мұрғаб аңғары.\n              Сақ патшайымдары: <b>Томирис</b> (б.з.б. 530 ж. парсы патшасы Кирді жеңді), <b>Зарина</b> (мидиялық Стриангиямен соғысты), <b>Шырақ</b> (б.з.б. 519 ж. І Дарий әскерін шөлге адастырған батыр).</li>\n            <li><b>Үйсіндер (б.з.б. III ғ. – б.з. IV ғ.):</b> Жетісу, астанасы — <b>Чигучен</b> (Қызыл аңғар, Ыстықкөл жағасы), билеушісі — <b>Гуньмо (Күнби)</b>. Ескерткіші: <b>Қарғалы тәтісі</b> (диадемасы).</li>\n            <li><b>Қаңлылар (б.з.б. III ғ. – б.з. V ғ.):</b> Сырдарияның орта ағысы, Қаратау, астанасы — <b>Битянь</b>, билеушісі — <b>Ұлы хан</b>. Мәдениеттері: <b>Қауыншы, Отырар-Қаратау, Жетіасар</b>.</li>\n            <li><b>Ғұндар (Хунну):</b> Негізін салушы — <b>Мөде шаньюй</b> (б.з.б. 209 ж.). Б.з.б. 55 ж. екіге бөлінді (Оңтүстік — Хуханье, Солтүстік/Батыс — <b>Чжи-Чжи</b>). «Халықтардың ұлы қоныс аударуын» бастады. Батыс ғұн империясының билеушісі — <b>Еділ (Аттила, 400–453 ж.)</b>, 451 ж. Каталаун шайқасы. Зергерлік өнерде — <b>полихромдық стиль</b> (дән мен қырнау).</li>\n            <li><b>Сарматтар (б.з.б. VIII ғ. – б.з. IV ғ.):</b> Батыс Қазақстан (савроматтар, дайлар, каспийлер, аландар). Ескерткіші: <b>Аралтөбе</b> (Атырау обл., З. Самашев — 2-ші Алтын адам), <b>Бесоба, Сынтас</b>.</li>\n          </ul>\n        ",
