        "easyExplanation": "\n          <h4>Қағанаттар кезеңі: хронология және орталықтары:</h4>\n          <ul>\n            <li><b>Түрік қағанаты (552–603 ж.):</b> Негізін қалаушы — <b>Бумын қаған</b> (552 ж. Жужандарды жеңді). <b>Мұқан қаған</b> тұсында күшейді, <b>Иштеми</b> батысқа жорық жасады (568 ж. Византияға Маниах елшілігі).</li>\n            <li><b>Батыс Түрік қағанаты (603–704 ж.):</b> «Он оқ бұдұн» (5 дулу, 5 нушеби). Астанасы — <b>Суяб</b> (жазғы ордасы — Мыңбұлақ). Қағандары: <b>Тардуш, Шегу, Тон-жабғу, Ешбар Елтеріс</b>.</li>\n            <li><b>Шығыс Түрік қағанаты (682–744 ж.):</b> Құтлық Елтеріс, Қапаған, <b>Білге қаған, Күлтегін</b> және кеңесшісі <b>Тоныкөк</b>.</li>\n            <li><b>Түргеш қағанаты (704–756 ж.):</b> Негізін қалаушы — <b>Үшлік қаған</b> (Сары және Қара түргештер). Астанасы — <b>Суяб</b> (кіші ордасы — Күнгіт). Даңқты қағаны — <b>Сұлу қаған (715–738 ж.)</b>, арабтар оны «Сүзеген (Мүйізді) қаған» деп атады. <b>751 ж. Атлах (Талас) шайқасы:</b> Араб + Қарлұқтар Қытай (Тан) әскерін талқандады.</li>\n            <li><b>Қарлұқ қағанаты (756–940 ж.):</b> Астанасы — <b>Суяб, Баласағұн</b>. Билеушісі — Жабғу (840 жылдан бастап Қаған).</li>\n            <li><b>Оғыз мемлекеті (IX ғ. соңы – XI ғ. басы):</b> Сырдарияның төменгі ағысы, астанасы — <b>Янгикент</b>. Билеушісі — <b>Жабғу</b>, мұрагері — Инал, әскербасы — <b>Сюбашы</b>. 965 ж. Киев кінәзі Святославпен одақтасып Хазарларды, 985 ж. Еділ Бұлғариясын жеңді.</li>\n            <li><b>Қимақ қағанаты (IX ғ. соңы – XI ғ. басы):</b> Солтүстік-Шығыс және Орталық Қазақстан, астанасы — <b>Имақия</b> (Ертіс бойында), екінші астанасы — Карантия. 7 тайпа (ең ірісі — <b>қыпшақтар</b>).</li>\n          </ul>\n        ",
