        "easyExplanation": "\n          <h4>XIII–XV ғасырлардағы мемлекеттік құрылымдар:</h4>\n          <ul>\n            <li><b>Моңғол империясы:</b> <b>1206 ж.</b> Темучин (Шыңғыс хан) хан сайланды. Негізгі заңы — <b>«Жасақ» (Яса)</b>. 1218 ж. «Отырар опаты» $\\rightarrow$ <b>1219–1224 ж.</b> Қазақстан мен Орта Азияны жаулау (Отырар 6 ай, Қайыр хан; Сығанақ 7 күн; Ашнас 15 күн).</li>\n            <li><b>Үш ұлыс:</b> 1) <b>Жошы ұлысы</b> (Ертістен Еділге дейін, Шығыс Дешті Қыпшақ); 2) <b>Шағатай ұлысы</b> (Жетісу, Оңт. Қазақстан, Мәуереннахр); 3) <b>Үгедей ұлысы</b> (Тарбағатай, Жоғарғы Ертіс).</li>\n            <li><b>Алтын Орда (Ұлық Ұлыс, 1242 – XV ғ. ортасы):</b> Негізін қалаушы — <b>Батый хан</b> (астанасы — Сарай-Бату). <b>Берке хан</b> (исламды қолдады, Мысыр сұлтаны Бейбарыспен байланыс), <b>Меңгу-Темір</b> (1266 ж. тәуелсіздік, өз теңгесін соқты), <b>Өзбек хан (1312–1342 ж.)</b> пен <b>Жәнібек хан</b> тұсында ең қуатты кезеңі (<b>1312 ж. Ислам мемлекеттік дін</b>, астанасы — Сарай-Берке). 1359–1379 ж. — «Ұлы дүрбелең».</li>\n            <li><b>Ақ Орда (XIII ғ. соңы – 1428 ж.):</b> Қазақ хандығының тікелей ізашары! Астанасы — <b>Сығанақ</b>. Хандары: <b>Орда Ежен, Сасы-Бұқа, Ерзен, Мүбәрак-Қожа, Орыс хан (1361–1377 ж.), Барақ хан (1423–1428 ж.)</b>.</li>\n            <li><b>Моғолстан (1348 – XVI ғ. басы):</b> Шығыс Шағатай ұлысы ыдыраған соң Жетісуда дулат әмірі <b>Болатшы</b> көмегімен <b>Тоғылық-Темір (1348–1362 ж.)</b> құрды. Астанасы — <b>Алмалық</b>. 1365 ж. «Батпақ шайқасы» (Ілияс-Қожа Әмір Темірді жеңді). Хандары: Қызыр-Қожа, Уәйіс, <b>Есен-бұға</b> (Керей мен Жәнібекті қарсы алды!).</li>\n            <li><b>Әбілқайыр хандығы («Көшпелі өзбектер мемлекеті», 1428–1468 ж.):</b> Астанасы — Тура (Чимги-Тура), Орда-Базар, 1446 жылдан — <b>Сығанақ</b>. 1457 ж. Сығанақ түбінде ойраттардан (Үз-Темір тайшыдан) жеңілісі Керей мен Жәнібектің Жетісуға көшуіне түрткі болды.</li>\n            <li><b>Ноғай Ордасы (Маңғыт жұрты):</b> Жайық пен Еділ аралығы, астанасы — <b>Сарайшық</b>. Негізін қалаушы — <b>Едіге</b>, баласы <b>Нұраддин</b> тұсында оқшауланды.</li>\n          </ul>\n        ",
