        "easyExplanation": "\n          <h4>Қазақ хандарының билік кезеңдері мен реформалары:</h4>\n          <ul>\n            <li><b>Қазақ хандығының құрылуы (1465 ж.):</b> <b>Керей</b> (Барақтың немересі, Болат сұлтанның ұлы — алғашқы хан) мен <b>Жәнібек</b> (Барақ ханның ұлы) Әбілқайыр ханнан бөлініп, Моғолстанның батысы <b>Жетісудағы Шу мен Қозыбасы</b> өңіріне қоныс аударды. Дереккөзі: <b>Мұхаммед Хайдар Дулати — «Тарих-и Рашиди»</b> (870 хижра жылы = 1465–1466 ж.).</li>\n            <li><b>Бұрындық хан (1480–1511 ж.)</b> — Керейдің ұлы, Сырдария бойындағы қалалар үшін Мұхаммед Шайбанимен күресті.</li>\n            <li><b>Қасым хан (1511–1518/1521 ж.):</b> Жәнібектің ұлы. Халық саны <b>1 миллионға</b> жетті, әскер саны 300 мың. Астанасы — <b>Сығанақ, Түркістан</b>. Заңдар жинағы — <b>«Қасым ханның қасқа жолы»</b> (5 бөлім: мүлік, қылмыс, әскери, елшілік, жұртшылық заңдары). Мәскеумен (III Василиймен) дипломатиялық байланыс орнатқан алғашқы хан.</li>\n            <li><b>Хақназар хан (1538–1580 ж.):</b> Қасымның ұлы. «Қазақ пен ноғайдың ханы». Хандықты «уақытша әлсіреуден» кейін қайта біріктірді. Өзбек ханы ІІ Абдаллахпен <b>«ант беріскен шарт»</b> жасасты, Иван Грозныймен елшілік алмасты.</li>\n            <li><b>Шығай хан (1580–1582 ж.):</b> 1582 ж. Баба сұлтанды талқандады.</li>\n            <li><b>Тәуекел хан (1582–1598 ж.):</b> Өзбек хандығымен соғысып, Түркістан, Ташкент, Самарқанд қалаларын басып алды. 1594 ж. Мәскеуге (Федор патшаға) <b>Құл-Мұхаммед</b> елшілігін жіберді (немере інісі Ораз-Мұхаммедті босату және «отты қару» алу үшін).</li>\n            <li><b>Есім хан (1598–1628 ж.):</b> 200 жылға созылған Сырдария қалалары үшін соғысты жеңіспен аяқтап, <b>Түркістанды</b> тұрақты астана етті! <b>«Есім ханның ескі жолы»</b> заңы. 1613–1627 ж. — <b>Тұрсын ханның</b> бүлігі («Қатаған қырғыны»).</li>\n            <li><b>Жәңгір хан (Салқам Жәңгір, 1628–1652 ж.):</b> <b>1643 ж. Орбұлақ шайқасы:</b> 600 қазақ сарбазымен (Жалаңтөс Баһадүрдің 20 мың әскері көмекке келді) Батыр қонтайшының 50 мыңдық жоңғар әскерін талқандады!</li>\n          </ul>\n        ",
