        "easyExplanation": "\n          <h4>XVIII ғасыр: Қазақ мемлекеттілігі және қайраткерлер:</h4>\n          <ul>\n            <li><b>Тәуке хан (1680–1715/1718 ж.):</b> «Адамзаттың данасы», билігі — «Қой үстіне бозторғай жұмыртқалаған заман». Ордасы — <b>Түркістан</b>, кеңестер — <b>Күлтөбе</b> мен Мәртөбеде. Үш жүздің ұлы билерімен (<b>Төле би</b> — Ұлы жүз, <b>Қазыбек би</b> — Орта жүз, <b>Әйтеке би</b> — Кіші жүз) <b>«Жеті жарғы»</b> заңдар жинағын қабылдады. 1710 ж. — <b>Қарақұм құрылтайы</b> (Бөгенбай батыр).</li>\n            <li><b>Жоңғар шапқыншылығы және жеңістер:</b>\n              1) <b>1718 ж.</b> — Аягөз шайқасы (Қайып пен Әбілқайыр).\n              2) <b>1723–1727 ж.</b> — «Ақтабан шұбырынды, Алқакөл сұлама» («Елім-ай» әні).\n              3) <b>1726 ж.</b> — <b>Ордабасы құрылтайы</b> (бас қолбасшы — Әбілқайыр хан) және <b>Бұланты-Білеуті шайқасы</b> («Қалмаққырылған»).\n              4) <b>1729/1730 ж.</b> — <b>Аңырақай шайқасы</b> (Балқаштың оңтүстігі, Итішпес Алакөл) — үш жүз жасағының түбегейлі жеңісі!</li>\n            <li><b>Абылай хан (Әбілмансұр, 1711–1781 ж., хандығы 1771–1781 ж.):</b> 20 жасында жекпе-жекте жоңғар батыры <b>Шарышты</b> өлтіріп, «Абылай» ұранымен танылды. Кеңесшісі — <b>Бұқар жырау</b>. Батырлары: <b>Қанжығалы Бөгенбай, Қаракерей Қабанбай, Шақшақ Жәнібек, Райымбек, Наурызбай, Баян, Малайсары</b>. Ресей мен Цинь (Қытай) империялары арасында шебер дипломатия жүргізіп, қазақ жерін қайтарды. 1771 ж. Түркістанда үш жүздің ханы болып сайланды.</li>\n          </ul>\n        ",
