        "easyExplanation": "\n          <h4>XVIII–XIX ғасырлардағы ұлт-азаттық қозғалыстар мен реформалар:</h4>\n          <ul>\n            <li><b>1731 ж. 10 қазан:</b> Кіші жүз ханы <b>Әбілқайырдың</b> Ресей патшайымы Анна Иоанновнаның бодандығын қабылдауы (елші <b>А.И. Тевкелев</b>, Ырғыз бойындағы Майтөбе).</li>\n            <li><b>Е. Пугачев көтерілісіне қатысу (1773–1775 ж.):</b> Кіші және Орта жүз қазақтары (Сырым Датұлы, Досалы сұлтан, Нұралы хан).</li>\n            <li><b>Сырым Датұлы көтерілісі (1783–1797 ж., Кіші жүз):</b> Нұралы хан биліктен шеттетілді, О. Игельстром реформасы, 1797 ж. Есім хан өлтірілді, <b>Хан кеңесі</b> құрылды (Айшуақ хан).</li>\n            <li><b>1822 ж. «Сібір қазақтары туралы Жарғы»:</b> Авторы — <b>М.М. Сперанский</b> (Декабрист Г. Батеньков қатысты). <b>Орта жүзде хандық билік жойылды!</b> Әкімшілік бөлініс: Ауыл (50–70 үй, ауыл старшыны) $\\rightarrow$ Болыс (10–12 ауыл, болыс сұлтаны) $\\rightarrow$ Округ (15–20 болыс, <b>аға сұлтан</b>, Приказ).</li>\n            <li><b>1824 ж. «Орынбор қазақтары туралы Жарғы»:</b> Авторы — <b>П.К. Эссен</b>. <b>Кіші жүзде хандық билік жойылды</b> (соңғы ханы — Шерғазы).</li>\n            <li><b>Исатай Тайманұлы мен Махамбет Өтемісұлы көтерілісі (1836–1838 ж., Бөкей Ордасы / Ішкі Орда):</b> Жәңгір хан мен Қарауылқожа Бабажанұлының езгісіне қарсы. Шайқастары: <b>Тастөбе (1837 ж. қараша)</b> және <b>Ақбұлақ (1838 ж. 12 шілде — Исатай қаза тапты)</b>.</li>\n            <li><b>Кенесары Қасымұлы көтерілісі (1837–1847 ж.):</b> <b>Үш жүзді түгел қамтыған ең ірі көтеріліс!</b> 1841 ж. қыркүйекте хан сайланып, Қазақ хандығын қалпына келтірді. 1847 ж. Кекілік-Сеңгір (Майтөбе) шайқасында қаза тапты.</li>\n            <li><b>Жоламан Тіленшіұлы (1822–1825 ж., Жаңаелек шебіне қарсы), Саржан мен Есенгелді Қасымұлдары (1825–1836 ж.), Жанқожа Нұрмұхамедұлы (Сырдария, 1856–1857 ж., Қазалы), Есет Көтібарұлы (Арал маңы, 1847–1858 ж.).</b></li>\n          </ul>\n        ",
