        "easyExplanation": "\n          <h4>Алаш қозғалысы және 1916–1917 жылдардағы оқиғалар:</h4>\n          <ul>\n            <li><b>1905 ж. Қарқаралы петициясы:</b> 14 500 адам қол қойды (Ә. Бөкейхан, А. Байтұрсынұлы, М. Дулатұлы).</li>\n            <li><b>«Қазақ» газеті (1913–1918 ж., Орынбор):</b> Бас редакторы — <b>Ахмет Байтұрсынұлы</b>, екінші редакторы — <b>Міржақып Дулатұлы</b> («Оян, қазақ!» 1909 ж.). «Айқап» журналы (1911–1915 ж., Троицк, М. Сералин).</li>\n            <li><b>1916 ж. Ұлт-азаттық көтеріліс:</b> Себебі — жерді тартып алу, түрткісі — ІІ Николай патшаның <b>1916 ж. 25 маусым жарлығы</b> (19 бен 43 жас аралығындағы ер адамдарды тыл жұмысына алу). Екі ірі орталығы:\n              1) <b>Торғай орталығы:</b> Хан — Әбдіғапар Жанбосынұлы, сардарбек — <b>Амангелді Иманов</b>, Кейкі батыр.\n              2) <b>Жетісу орталығы:</b> <b>Бекболат Әшекеев</b> (Үшқоңыр), <b>Тоқаш Бокин, Жәмеңке Мәмбетов, Ұзақ Саурықов</b> (Қарқара жәрмеңкесі).</li>\n            <li><b>Бірінші Жалпықазақ съезі (1917 ж. 21–26 шілде, Орынбор):</b> <b>«Алаш» партиясы</b> құрылды (бағдарламасы 10 бөлімнен тұрады, «Қазақ» газетінде жарияланды).</li>\n            <li><b>Екінші Жалпықазақ съезі (1917 ж. 5–13 желтоқсан, Орынбор):</b> <b>Алаш автономиясы</b> мен <b>Алашорда Халық Кеңесі (үкіметі, 25 орын, оның 10-ы өзге ұлттарға)</b> құрылды! Төрағасы — <b>Әлихан Бөкейхан</b>, уақытша орталығы — <b>Семей («Алаш» қаласы)</b>. Түркістан (Қоқан) автономиясы (1917 ж. қараша, М. Тынышбаев, М. Шоқай).</li>\n          </ul>\n        ",
