        "easyExplanation": "\n          <h4>1920–1945 жылдар: тарихи белестер, тұлғалар мен даталар:</h4>\n          <ul>\n            <li><b>Қазақ АКСР құрылуы (1920 ж. 26 тамыз декреті / 4–12 қазан Орынбор съезі):</b> Алғашқы астанасы — <b>Орынбор (1920–1925 ж.)</b>. ХКК төрағасы — В. Радус-Зенькович, ОАК төрағасы — <b>Сейітқали Меңдешев</b>. Қазақ жерлерін біріктіруде <b>Әлімхан Ермеков</b> В.И. Ленин алдында баяндама жасады.</li>\n            <li><b>Астаналар хронологиясы:</b> Орынбор (1920–1925) $\\rightarrow$ <b>Қызылорда (1925–1929)</b> (1925 ж. сәуірде «қырғыз» атауы <b>«қазақ»</b> деп қайтарылды!) $\\rightarrow$ <b>Алматы (1929–1997)</b> $\\rightarrow$ Ақмола / Астана (1997 жылдан).</li>\n            <li><b>Индустрияландыру (1925 ж. XIV съезд):</b> Ең басты құрылыс — <b>Түркістан–Сібір (Түрксіб) теміржолы (1927–1930 ж.)</b>, басшылары: <b>Тұрар Рысқұлов, Мұхамеджан Тынышбаев, Нұрпейіс Есенаманов, В. Шатов</b> (Айнабұлақ бекетінде түйісті). Ф.И. Голощекиннің «Кіші Қазан» саясатына <b>Смағұл Сәдуақасов</b> пен <b>Жалау Мыңбаев</b> қарсы шықты.</li>\n            <li><b>Күштеп ұжымдастыру және Ұлы Нәубет (1931–1933 ж.):</b> 2.1 миллионнан астам қазақ (халықтың ~49%-ы) аштықтан қырылды. Сталинге хаттар: <b>Т. Рысқұлов хаты</b> және <b>«Бесеудің хаты» (1932 ж. шілде: Ғ. Мүсірепов, М. Ғатауллин, М. Дәулетқалиев, Е. Алтынбеков, Қ. Қуанышев)</b>.</li>\n            <li><b>1936 ж. 5 желтоқсан:</b> Қазақ АКСР-і одақтас республика — <b>Қазақ КСР-і</b> болып қайта құрылды!</li>\n            <li><b>1937–1938 ж. Саяси қуғын-сүргін (Үлкен террор):</b> Алаш арыстары атылды. Лагерьлер: <b>АЛЖИР</b> (Ақмола), <b>Қарлаг</b> (Қарағанды), <b>Степлаг</b> (Жезқазған).</li>\n            <li><b>Ұлы Отан соғысы (1941–1945 ж.):</b> Қазақстаннан 1 млн 200 мың адам майданға аттанды. ~500 қазақстандық (оның ~100-і қазақ) Кеңес Одағының Батыры атанды. <b>Екі мәрте батырлар (4 ұшқыш): Талғат Бигелдинов, Леонид Беда, Иван Павлов, Сергей Луганский</b>. <b>Шығыстың қос жұлдызы: Әлия Молдағұлова</b> (мерген) мен <b>Мәншүк Мәметова</b> (пулеметші), ұшқыш <b>Хиуаз Доспанова</b>. Рейхстагқа алғаш ту тіккен — <b>Рақымжан Қошқарбаев</b> (1945 ж. 30 сәуір). 316-шы атқыштар дивизиясы (генерал И.В. Панфилов, <b>Бауыржан Момышұлы</b>, Мәлік Ғабдуллин, Төлеген Тоқтаров). Майданда атылған әрбір 10 оқтың 9-ы Қазақстан қорғасынынан құйылды!</li>\n          </ul>\n        ",
