        "easyExplanation": "\n          <h4>1946 жылдан бүгінге дейін: Тәуелсіздік шежіресі:</h4>\n          <ul>\n            <li><b>1946 ж. 1 маусым:</b> <b>Қазақ КСР Ғылым академиясы</b> ашылды, тұңғыш президенті — <b>Қаныш Сәтбаев</b>.</li>\n            <li><b>«Бекмаханов ісі» (1952 ж.):</b> Тарихшы <b>Ермұхан Бекмаханов</b> Кенесары Қасымұлы туралы монографиясы үшін 25 жылға сотталды (1954 ж. ақталды).</li>\n            <li><b>Семей ядролық полигоны:</b> Алғашқы жарылыс — <b>1949 ж. 29 тамыз</b>. 40 жыл ішінде 450-ден астам сынақ жасалды. 1989 ж. <b>Олжас Сүлейменов</b> бастаған «Невада–Семей» қозғалысы құрылды, <b>1991 ж. 29 тамызда</b> полигон жабылды!</li>\n            <li><b>Тың және тыңайған жерлерді игеру (1954 ж.):</b> Ж. Шаяхметов орнынан алынып, П. Пономаренко мен Л. Брежнев келді. 1959 ж. — <b>Теміртау оқиғасы</b>.</li>\n            <li><b>Дінмұхамед Ахметұлы Қонаев (1960–1962, 1964–1986 ж.):</b> 43 жаңа қала салынды. <b>1979 ж. маусымда Целиноградта (Ақмолада)</b> Неміс автономиясын құруға қарсы жастар шеруі өтті.</li>\n            <li><b>1986 ж. 16–18 желтоқсан көтерілісі (Алматы):</b> Қонаевтың орнына Г. Колбиннің тағайындалуына қарсы. Құрбандары: <b>Қайрат Рысқұлбеков</b> («Халық қаһарманы»), <b>Ербол Сыпатаев, Ләззат Асанова, Сәбира Мұхамеджанова</b>.</li>\n            <li><b>Тәуелсіз Қазақстанның алтын даталары:</b>\n              - <b>1989 ж. 22 қыркүйек:</b> «Тілдер туралы заң» (қазақ тілі — мемлекеттік тіл).\n              - <b>1990 ж. 25 қазан:</b> Мемлекеттік Егемендік туралы Декларация (Республика күні!).\n              - <b>1991 ж. 2 қазан:</b> Тұңғыш қазақ ғарышкері <b>Тоқтар Әубәкіров</b> ғарышқа ұшты (1994, 1998, 2001 ж. — <b>Талғат Мұсабаев</b>; 2015 ж. — <b>Айдын Айымбетов</b>).\n              - <b>1991 ж. 16 желтоқсан:</b> «Қазақстан Республикасының Мемлекеттік тәуелсіздігі туралы» Конституциялық Заң!\n              - <b>1992 ж. 2 наурыз:</b> Қазақстан <b>БҰҰ-ға (ООН)</b> мүше болды!\n              - <b>1992 ж. 4 маусым:</b> Мемлекеттік рәміздер бекітілді (Ту — <b>Шәкен Ниязбеков</b>, Елтаңба — <b>Жандарбек Мәлібеков</b> пен <b>Шота Уәлиханов</b>).\n              - <b>1993 ж. 28 қаңтар:</b> Тәуелсіз ҚР тұңғыш Конституциясы.\n              - <b>1993 ж. 15 қараша:</b> Ұлттық валюта — <b>Теңге</b> айналымға енді!\n              - <b>1995 ж. 30 тамыз:</b> Қолданыстағы ҚР Конституциясы (референдум).\n              - <b>1997 ж. 10 желтоқсан:</b> Астана Алматыдан Ақмолаға (Астанаға) көшірілді.\n              - <b>2010 ж. 1–2 желтоқсан:</b> Астанада ЕҚЫҰ (ОБСЕ) Саммиті; <b>2017 ж.</b> — ЭКСПО-2017 («Болашақ энергиясы»).\n              - <b>2019 ж.</b> — <b>Қасым-Жомарт Тоқаев</b> ҚР Президенті болып сайланды; <b>2022 ж. 5 маусым</b> — Конституциялық реформа референдумы («Әділетті Қазақстан»).</li>\n          </ul>\n        ",
