        "title": "48–55 Қазақ халқының материалдық және рухани мәдениеті: Ортағасырлық ғалымдар, Жыраулар, ХІХ ғ. Ағартушылары (Шоқан, Ыбырай, Абай), Күйшілер және Ғылым",
        "easyExplanation": "\n          <h4>Қазақ руханияты: ғалымдар, ақын-жыраулар мен күйшілер:</h4>\n          <ul>\n            <li><b>Ортағасырлық ғұламалар мен шығармалар:</b>\n              1) <b>Әбу Насыр әл-Фараби (870–950 ж., Отырар/Фараб):</b> «Екінші ұстаз» («Қайырымды қала тұрғындарының көзқарастары», «Музыканың үлкен кітабы», «Ғылымдарды классификациялау»).\n              2) <b>Жүсіп Баласағұни (XI ғ.):</b> «Құтты білік» («Кутадгу билиг», 1069 ж.) — түрік тіліндегі алғашқы дидактикалық дастан, Сатұқ Боғра ханның ұрпағы Сүлеймен Арслан ханға сыйлап, «Ұлы хас хажиб» лауазымын алды.\n              3) <b>Махмұд Қашқари (XI ғ.):</b> «Диуани лұғат ат-түрік» («Түркі тілдерінің сөздігі», 3 том).\n              4) <b>Қожа Ахмет Ясауи (XII ғ., Сайрам–Түркістан):</b> «Диуани хикмет» («Даналық кітабы»), сопылық ілім, ұстазы — <b>Арыстан баб</b>. Кесенесін XIV ғ. соңында <b>Әмір Темір</b> салдырды.\n              5) <b>Мұхаммед Хайдар Дулати (1499–1551 ж.):</b> «Тарих-и Рашиди» (парсы тілінде, Қазақ хандығының құрылуы туралы басты дерек).\n              6) <b>Қадырғали Жалайыри (1530–1605 ж.):</b> «Жами ат-тауарих» («Жылнамалар жинағы», Ораз-Мұхаммедпен бірге Мәскеуде Борис Годунов тұсында жазды).</li>\n            <li><b>Сәулет ескерткіштері:</b> Х–ХІІ ғ. — <b>Бабаджа-қатын, Айша-бибі</b> (Тараз маңы), <b>Алаша хан, Жошы хан</b> (Ұлытау), <b>Қожа Ахмет Ясауи</b> (Түркістан).</li>\n            <li><b>XV–XVIII ғ. Жыраулар:</b> <b>Асан қайғы</b> (Керей мен Жәнібек тұсы, «Жерұйық»), <b>Қазтуған, Доспамбет, Шалкиіз, Жиембет</b> (Есім хан тұсы), <b>Марғасқа, Ақтамберді, Тәтіқара, Үмбетей</b>, <b>Бұқар жырау Қалқаманұлы</b> (Абылай ханның кеңесшісі — «Көмекей әулие»).</li>\n            <li><b>ХІХ ғ. Ұлы ағартушылары:</b>\n              1) <b>Шоқан Уәлиханов (Мұхаммед-Қанафия, 1835–1865 ж.):</b> Сырымбет, Сібір кадет корпусы (Омбы), 1856 ж. Ыстықкөл мен Құлжа экспедициясы («Манас» жырын жазып алды), <b>1858–1859 ж. Қашғарияға саяхаты</b> (Әлімбай көпес атымен).\n              2) <b>Ыбырай Алтынсарин (1841–1889 ж.):</b> 1864 ж. Торғайда қазақ балаларына мектеп ашты, 1879 ж. «Қазақ хрестоматиясы» («Кел, балалар, оқылық!»), 1887 ж. Ырғызда тұңғыш қыздар мектеп-интернатын ашты.\n              3) <b>Абай (Ибраһим) Құнанбайұлы (1845–1904 ж.):</b> Қазақ жазба әдебиетінің негізін салушы, <b>45 Қара сөз</b>, 3 поэма («Ескендір», «Масғұт», «Әзім әңгімесі»).</li>\n            <li><b>ХІХ ғ. Күйші-композиторлар мен әншілер:</b>\n              - <b>Құрманғазы Сағырбайұлы</b> (Төкпе күй атасы: «Адай», «Сарыарқа», «Кішкентай» — Исатайға арналған, «Балбырауын», «Серпер»).\n              - <b>Дәулеткерей Шығайұлы</b> (Лирикалық төкпе күй: «Қос алқа», «Құдаша»).\n              - <b>Тәттімбет Қазанғапұлы</b> (Шертпе күй атасы: «Саржайлау», «Көкейкесті», «Сылқылдақ»).\n              - <b>Ықылас Дүкенұлы</b> (Қобызшы: «Жезкиік», «Қамбар батыр», «Ерден»).\n              - <b>Біржан сал Қожағұлұлы, Ақан сері Қорамсаұлы, Жаяу Мұса Байжанұлы, Мұхит Мералыұлы, Балуан Шолақ, Үкілі Ыбырай, Мәди Бәпиұлы.</b></li>\n          </ul>\n        ",
